RSpec.describe Timekeeping::Handoff::Runner do
  it "refuses a cutover with no monolith admission adapter before fencing Timekeeping or writing any report" do
    timekeeping_admission = Class.new do
      attr_reader :calls

      def initialize
        @calls = []
      end

      def enforces_fence? = true

      def fence_admission
        @calls << [:fence]
        nil
      end

      def admit(generation:)
        @calls << [:admit, generation]
        nil
      end
    end.new
    store = Object.new
    owners = {
      monolith: Timekeeping::Handoff::Owner.new(name: "monolith", store:, admission: nil, settle: nil, drain: nil),
      timekeeping: Timekeeping::Handoff::Owner.new(name: "timekeeping", store:, admission: timekeeping_admission,
                                                   settle: nil, drain: nil)
    }
    before = TimekeepingOwnership.current.attributes.slice("generation", "handoff_step", "owner", "final_outbox_position",
                                                           "monolith_store", "legacy_retired_at")
    expect(before).to include("generation" => 1, "handoff_step" => nil)

    Dir.mktmpdir do |report_root|
      # "So, before raising the generation, the runner refuses to start unless both conditions hold."
      # A gate placed after step 1's fence call would leave Timekeeping fenced with no handoff recorded.
      expect do
        described_class.run(direction: :cutover, owners:, report_root:)
      end.to raise_error(Timekeeping::Handoff::Runner::Refused)

      expect(timekeeping_admission.calls).to be_empty
      expect(Dir.children(report_root)).to be_empty
    end

    # "A refusal leaves the generation and `handoff_step` unchanged."
    after = TimekeepingOwnership.current.attributes.slice(*before.keys)
    expect(after).to eq(before)
  end
end
